package com.example.starter.domain;

/**
 * 重要用户保电等级（合成分级），数值越小优先级越高。
 */
public enum Grade {
    /** 特级：停电满 5 分钟启动发电车流程 */
    SPECIAL(0),
    /** 一级 */
    FIRST(1),
    /** 二级 */
    SECOND(2),
    /** 普通 */
    NORMAL(3);

    private final int priority;

    Grade(int priority) {
        this.priority = priority;
    }

    public int priority() {
        return priority;
    }

    /**
     * 返回两个等级中更优先（数值更小）的等级，均为空时返回 NORMAL。
     */
    public static Grade higher(Grade a, Grade b) {
        if (a == null) {
            return b == null ? NORMAL : b;
        }
        if (b == null) {
            return a;
        }
        return a.priority <= b.priority ? a : b;
    }
}

package com.example.starter.domain;

/**
 * 故障工单状态，流转：REPORTED→ASSESSED→(WAITING)→DISPATCHED→REPAIRING→RESTORED→SEALED；
 * MERGED 与 SEALED 为终态。
 */
public enum OrderStatus {
    /** 已接报，待研判 */
    REPORTED,
    /** 已研判，进入派单队列 */
    ASSESSED,
    /** 资源冲突挂单等待 */
    WAITING,
    /** 已派单 */
    DISPATCHED,
    /** 抢修中 */
    REPAIRING,
    /** 已复电（调度与现场双确认齐备） */
    RESTORED,
    /** 日结封存（终态） */
    SEALED,
    /** 已合并，引用新单（终态） */
    MERGED
}

package com.example.starter.domain;

/**
 * 复电确认/事件主体。
 */
public enum ActorType {
    /** 调度 */
    DISPATCHER,
    /** 现场（抢修班组） */
    FIELD,
    /** 系统（自动判定） */
    SYSTEM,
    /** 报修人 */
    CALLER
}

