    Integer n = jdbc.queryForObject(
            "SELECT COUNT(*) FROM fault_order WHERE feeder_id = ?"
                    + " AND status IN ('REPORTED', 'ASSESSED', 'WAITING', 'DISPATCHED', 'REPAIRING')",
            Integer.class, feederId);
    return n == null ? 0 : n;
}

